div#olddiv {
  font: 100% "open_sansregular", sans-serif, Arial, Verdana, Helvetica;
  background-color: white;
  color: #2a2a2a;
  margin: 0;
  padding: 0;
  line-height: 125%;
}
div#olddiv table.tip01 tr.rowh td {
  background-color: #2a2a2a;
  color: #ffffff;
  font-weight: bold;
}
div#olddiv table.tip01 tr.rowt td {
  background-color: #e7c24f;
  color: #730a49;
  font-weight: bold;
  padding: 5px;
}
div#olddiv a {
  color: #2a2a2a;
  background-color: transparent;
  text-decoration: none;
}
div#olddiv a:hover {
  color: #0000FF;
  text-decoration: underline;
}

body {
  background: url('../img/bgbody.jpg') repeat;
  font-size: 11px;
}
#page {
  width: 100%;
  max-width: 960px;
  min-width: 320px;
  margin: 0 auto;
}
a {
  color: #2f598c;
  font-size: 13px;
  text-decoration: none;
}
